#include "native_dvd_port.hpp"
#include <cassert>
#include <cstdio>
#include <atomic>
#include <thread>
#include <revolution/dvd.h>
extern "C" int DVDConvertPathToEntrynum(const char*);
std::atomic<int> callbackResult{-99};std::thread::id submittingThread;void completed(s32 result,DVDFileInfo* info){assert(std::this_thread::get_id()!=submittingThread);assert(DVDGetCommandBlockStatus(&info->cb)==0);callbackResult.store(result);}
std::atomic<int> diskCheckResult{-1};void diskChecked(s32 result,DVDCommandBlock*){diskCheckResult.store(result);}
int main(int argc,char** argv){assert(argc==2);assert(DVDGetCommandBlockStatus(nullptr)==-1);DVDCommandBlock status{};for(s32 state=-3;state<=11;++state){status.state=state;assert(DVDGetCommandBlockStatus(&status)==(state==3?1:state==5?4:state));}DVDInit();assert(!nativeDvdIsBound());assert(DVDGetDriveStatus()==DVD_STATE_END);DVDCommandBlock diskCheck{};assert(DVDCheckDiskAsync(&diskCheck,diskChecked));assert(diskCheckResult.load()==FALSE&&diskCheck.state==0);assert(DVDConvertPathToEntrynum("/")==-1);assert(nativeBindDvd(std::filesystem::u8path(argv[1])));assert(nativeDvdIsBound());diskCheckResult=-1;assert(DVDCheckDiskAsync(&diskCheck,diskChecked));assert(diskCheckResult.load()==TRUE&&diskCheck.state==0);assert(DVDGetDriveStatus()==DVD_STATE_END);assert(DVDConvertPathToEntrynum("/")==0);int font=DVDConvertPathToEntrynum("/LayoutData/Font.arc");assert(font>0 && font==DVDConvertPathToEntrynum("layoutdata/font.ARC"));int jaiSeq=DVDConvertPathToEntrynum("/AudioRes/Seqs/JaiSeq.arc");assert(jaiSeq>0);DVDFileInfo jaiInfo{};assert(DVDOpen("/AudioRes/Seqs/JaiSeq.arc",&jaiInfo));assert(jaiInfo.length==142400);assert(DVDClose(&jaiInfo));assert(DVDConvertPathToEntrynum("/missing")==-1);DVDFileInfo info{};assert(!DVDFastOpen(0,&info));assert(!DVDFastOpen(-1,&info));assert(!DVDOpen("/missing",&info));assert(DVDFastOpen(font,&info));WiiAssets reference(std::filesystem::u8path(argv[1]));auto bytes=reference.readFile("/LayoutData/Font.arc");std::vector<uint8_t> entryBytes;assert(nativeReadDvdEntry(font,entryBytes));assert(entryBytes==bytes);assert(!nativeReadDvdEntry(0,entryBytes));assert(entryBytes==bytes);assert(info.length==bytes.size() && info.startAddr>0);assert(reference.read(uint64_t(info.startAddr)*4,info.length)==bytes);std::vector<uint8_t> output(bytes.size());assert(DVDReadPrio(&info,output.data(),s32(output.size()),0,2)==s32(bytes.size()));assert(output==bytes);assert(info.cb.transferredSize==bytes.size());assert(DVDGetCommandBlockStatus(&info.cb)==0);for(s32 offset: {0,4,32,1024,65536}){uint8_t chunk[64];assert(DVDReadPrio(&info,chunk,64,offset,2)==64);assert(std::equal(chunk,chunk+64,bytes.data()+offset));}uint8_t tail[32]{};assert(DVDReadPrio(&info,tail,31,s32(bytes.size()),2)==31);assert(reference.read(uint64_t(info.startAddr)*4+(bytes.size()/4)*4,31)==std::vector<uint8_t>(tail,tail+31));assert(DVDReadPrio(&info,tail,32,s32(bytes.size()),2)==-1);assert(DVDReadPrio(&info,tail,1,-1,2)==-1);assert(DVDReadPrio(&info,nullptr,1,0,2)==-1);assert(!DVDFastOpen(font,&info));assert(DVDClose(&info));assert(!DVDClose(&info));assert(DVDReadPrio(&info,tail,1,0,2)==-1);assert(DVDOpen("/LayoutData/Font.arc",&info));submittingThread=std::this_thread::get_id();output.assign(bytes.size(),0);assert(DVDReadAsyncPrio(&info,output.data(),s32(output.size()),0,completed,2));assert(DVDClose(&info));assert(callbackResult.load()==s32(bytes.size()));assert(output==bytes);assert(!DVDReadAsyncPrio(&info,output.data(),32,0,completed,2));assert(DVDOpen("/LayoutData/Font.arc",&info));callbackResult=-99;assert(DVDReadAsyncPrio(&info,output.data(),32,0,completed,2));nativeReleaseDvd();assert(callbackResult.load()==32);assert(!nativeDvdIsBound());assert(!DVDClose(&info));assert(DVDConvertPathToEntrynum("/")==-1);std::printf("PASS native DVD verified FST IDs: Font.arc=%d JaiSeq.arc=%d\n",font,jaiSeq);}






